package org.evchargingplatform.reservation.adapter.out.persistence;
import org.evchargingplatform.reservation.domain.*; import org.evchargingplatform.reservation.domain.repository.ReservationRepository; import org.evchargingplatform.reservation.infrastructure.persistence.*; import org.springframework.stereotype.Component; import java.time.Instant; import java.util.*;
@Component public class ReservationJpaAdapter implements ReservationRepository { private final ReservationJpaRepository repository; public ReservationJpaAdapter(ReservationJpaRepository repository){this.repository=repository;} public Reservation save(Reservation r){return toDomain(repository.save(toEntity(r)));} public Optional<Reservation> findById(UUID id){return repository.findById(id).map(this::toDomain);} public List<Reservation> findAll(){return repository.findAll().stream().map(this::toDomain).toList();} public List<Reservation> findExpired(Collection<ReservationStatus> s,Instant at){return repository.findByStatusInAndExpirationTimeBefore(s,at).stream().map(this::toDomain).toList();} private ReservationEntity toEntity(Reservation r){return new ReservationEntity(r.id(),r.reservationNumber(),r.stationId(),r.chargerId(),r.userId(),r.vehicleId(),r.startTime(),r.expirationTime(),r.status(),r.createdAt(),r.updatedAt());} private Reservation toDomain(ReservationEntity e){return new Reservation(e.getId(),e.getReservationNumber(),e.getStationId(),e.getChargerId(),e.getUserId(),e.getVehicleId(),e.getStartTime(),e.getExpirationTime(),e.getStatus(),e.getCreatedAt(),e.getUpdatedAt());} }
